#!/bin/bash
# Generated By: Claude Code (claude-opus-5)
#
# One rule under test: the managed settings that deny Anthropic models reach a
# work sandbox only, and the sandbox cannot edit them.
#
# `deniedModels` is honored only from managed settings, and the Linux path is
# /etc/claude-code/managed-settings.json — root-owned, with /etc read_only in
# every policy. A runtime upload would need a writable destination, and anything
# the sandbox user can write the agent can rewrite to unblock the models. So the
# file is baked into a work-only derived image, from the host's file at build
# time. Personal and home run the base image and get no managed settings.
#
# Covers: image selection by profile, the work image's root-owned COPY, the
# build-time staging (present and absent source), and the base image staying
# clean.
#
# Run: tests/test-managed-settings.sh

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SANDBOX_SH="${REPO_ROOT}/scripts/sandbox.sh"
MAKEFILE="${REPO_ROOT}/Makefile"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

# shellcheck source=/dev/null
source "${REPO_ROOT}/scripts/lib.sh"

fail=0

# --- image selection: work only gets the derived image ---
[[ "$(sandbox_image_for work)" == "openshell-sandbox-work:latest" ]] \
    || { echo "FAIL: work does not select the managed-settings image" >&2; fail=1; }
for profile in personal home; do
    [[ "$(sandbox_image_for "$profile")" == "openshell-sandbox:latest" ]] \
        || { echo "FAIL: ${profile} selects an image with managed settings" >&2; fail=1; }
done
[[ "$(SANDBOX_IMAGE_NAME=img SANDBOX_IMAGE_TAG=t sandbox_image_for work)" == "img-work:t" ]] \
    || { echo "FAIL: image name/tag overrides are not honored" >&2; fail=1; }

# --- the base image must not carry the file ---
if grep -q 'managed-settings' "${REPO_ROOT}/Containerfile"; then
    echo "FAIL: the base image bakes managed settings; personal/home would deny Anthropic models" >&2
    fail=1
fi

# --- the work image bakes it root-owned at the managed path ---
grep -qF 'COPY --chown=root:root .tmp-managed-settings.json /etc/claude-code/managed-settings.json' \
    "${REPO_ROOT}/Containerfile.work" \
    || { echo "FAIL: the work image does not bake a root-owned managed-settings file" >&2; fail=1; }

# --- the policies keep /etc read-only and grant no path into it ---
for policy in work personal home; do
    grep -qx '    - /etc' "${REPO_ROOT}/policies/${policy}.yaml" \
        || { echo "FAIL: ${policy}.yaml no longer makes /etc read-only" >&2; fail=1; }
done
if grep -q 'claude-code' "${REPO_ROOT}"/policies/*.yaml; then
    echo "FAIL: a policy grants write access to /etc/claude-code" >&2
    fail=1
fi

# --- hosting wiring ---
grep -qF -- '--from "$(sandbox_image_for "$SANDBOX_PROFILE")"' "$SANDBOX_SH" \
    || { echo "FAIL: sandbox create no longer selects the image by profile" >&2; fail=1; }
grep -qF 'Containerfile.work' "$MAKEFILE" \
    || { echo "FAIL: make no longer builds the work image" >&2; fail=1; }
grep -qF '$(WORK_IMAGE_REF)' "$MAKEFILE" \
    || { echo "FAIL: make no longer names the work image" >&2; fail=1; }

# --- build-time staging copies the host file, and refuses an absent one ---
SRC="${TMP}/host-managed-settings.json"
STAGED="${TMP}/staged.json"
cat > "$SRC" << 'JSON'
{"deniedModels": ["fable", "haiku", "opus", "sonnet"]}
JSON
make -s --no-print-directory -C "$REPO_ROOT" stage-managed-settings \
    MANAGED_SETTINGS_SRC="$SRC" MANAGED_SETTINGS_STAGE="$STAGED"
jq -e '.deniedModels == ["fable", "haiku", "opus", "sonnet"]' "$STAGED" >/dev/null \
    || { echo "FAIL: staging did not copy the host's deny list" >&2; fail=1; }

if make -s --no-print-directory -C "$REPO_ROOT" stage-managed-settings \
        MANAGED_SETTINGS_SRC="${TMP}/does-not-exist.json" \
        MANAGED_SETTINGS_STAGE="${TMP}/never.json" >/dev/null 2>&1; then
    echo "FAIL: staging succeeded with no source; a work image would run unblocked" >&2
    fail=1
fi
[[ ! -e "${TMP}/never.json" ]] \
    || { echo "FAIL: staging wrote a file from an absent source" >&2; fail=1; }

[[ $fail -eq 0 ]] && echo "all managed-settings checks passed"
exit $fail
